#[method(name = "deploy_contract")]
async fn deploy_contract(&self, deploy_contract: PQBCDeployContractV2<Hash>) -> RpcResult<String>;

#[method(name = "update_contract")]
async fn update_contract(&self, update_contract: PQBCUpdateContract<Hash>) -> RpcResult<String>;

async fn deploy_contract(&self, deploy_contract: PQBCDeployContractV2<N::QHash>) -> QRpcResult<String> {
    res(self.deploy_contract_internal(deploy_contract).await)
}
async fn update_contract(&self, update_contract: PQBCUpdateContract<N::QHash>) -> QRpcResult<String> {
    res(self.update_contract_internal(update_contract).await)
}

pub async fn update_contract_internal(&self, update_contract: PQBCUpdateContract<N::QHash>) -> anyhow::Result<String> {
    update_contract.validate_shape()?;
    if update_contract.code_definition.functions.len() == 0 {
        anyhow::bail!("contracts with no functions are not supported");
    } else if update_contract.code_definition.functions.len() > (1usize << N::CONTRACT_FUNCTION_TREE_HEIGHT) {
        anyhow::bail!("contract has too many functions defined");
    }

    if update_contract.contract_id == 0 {
        anyhow::bail!("contract id 0 is reserved and cannot be updated");
    }

    // Auth check: the contract must already exist on chain and the caller must
    // be the original deployer. NOTE: db_reader reflects the last committed
    // checkpoint state; updates gathered in the current pending block are not
    // visible here, so the gatherer must re-validate against its in-memory
    // global contract tree (TODO in the update contract gatherer phase).
    let latest_checkpoint_id =
        self.get_latest_checkpoint_id_internal().await?;
    let existing_leaf = self
        .db_reader
        .get_contract_leaf(
            latest_checkpoint_id,
            update_contract.contract_id,
        )
        .await
        .map_err(|_| anyhow::anyhow!("contract with id {} does not exist", update_contract.contract_id))?;

    if existing_leaf.deployer != update_contract.deployer {
        anyhow::bail!(
            "only the original deployer can update contract {}",
            update_contract.contract_id
        );
    }
    anyhow::ensure!(
        existing_leaf.state_tree_height.to_u64_value()
            == update_contract.code_definition.state_tree_height as u64,
        "contract state tree height is immutable"
    );

    self.validate_canonical_layout_proof(
        update_contract.canonical_layout_verifier_fingerprint,
        &update_contract.canonical_layout_proof,
    )
    .await?;

#[pderive::serialize_clone_hash_ts]
#[ts(export, concrete(Hash = parth_core::PHash), rename = "QBCUpdateContract")]
pub struct PQBCUpdateContract<Hash> {
    pub contract_id: u64,
    pub deployer: Hash,
    pub code_definition: ContractCodeDefinition,
    pub function_whitelist: Vec<Hash>,
    pub code_root: Hash,
    pub layout_protocol_version: u16,
    pub state_layout_root: Hash,
    pub state_layout_field_count: u64,
    pub state_layout_slot_count: u64,
    pub canonical_layout_verifier_fingerprint: Hash,
    pub canonical_layout_proof: Vec<u8>,
}

impl<Hash: QHashBase> PQBCUpdateContract<Hash> {
    pub fn validate_shape(&self) -> anyhow::Result<()> {
        anyhow::ensure!(
            self.contract_id != 0,
            "update contract id must be non-zero"
        );
        anyhow::ensure!(
            self.layout_protocol_version != 0,
            "layout protocol version must be non-zero"
        );
        anyhow::ensure!(
            !self.canonical_layout_proof.is_empty(),
            "canonical layout proof is empty"
        );
        anyhow::ensure!(
            self.canonical_layout_proof.len()
                <= psy_core::constants::protocol::
                    STATE_LAYOUT_MAX_PROOF_BYTES,
            "canonical layout proof exceeds maximum size"
        );
        anyhow::ensure!(
            self.state_layout_field_count <= self.state_layout_slot_count,
            "layout field count exceeds slot count"
        );
        anyhow::ensure!(
            self.code_definition.state_tree_height < 64
                && self.state_layout_slot_count
                    <= (1u64 << self.code_definition.state_tree_height) * 4,
            "layout slot count exceeds contract state capacity"
        );
        Ok(())
